//! The programs `run` can start.
//!
//! USER_PROGRAMS is generated by build.rs from userland/src/bin (Rust ELF
//! programs). FLAT_PROGRAMS are raw assembly binaries from src/user_progs.
//! At boot they're all copied into /bin.

include!(concat!(env!("OUT_DIR"), "/user_programs.rs"));

pub static FLAT_PROGRAMS: &[(&str, &[u8])] = &[
    ("test_crash", include_bytes!("user_progs/crash.bin")),
];

/// Install every bundled program as /bin/<name>, so programs can be run by
/// path (execve("/bin/ls", ...)) like on any Unix.
/// Put every bundled program in /bin. Returns how many (and their size).
pub fn install() -> (usize, usize) {
    let _ = crate::filesystem::make_dir("/bin");
    let (mut count, mut bytes_total) = (0, 0);
    for (name, bytes) in USER_PROGRAMS.iter().chain(FLAT_PROGRAMS) {
        count += 1;
        bytes_total += bytes.len();
        let path = alloc::format!("/bin/{}", name);
        crate::filesystem::write_bytes(&path, bytes).expect("can't write /bin entry");
        // Executable; su and passwd are setuid root (they switch users and
        // edit /etc/shadow on behalf of ordinary users).
        let mode = if matches!(*name, "su" | "passwd") { 0o4755 } else { 0o755 };
        let _ = crate::filesystem::chmod(&path, mode);
    }
    (count, bytes_total)
}

/// Look up a bundled program by name.
pub fn find(name: &str) -> Option<&'static [u8]> {
    USER_PROGRAMS
        .iter()
        .chain(FLAT_PROGRAMS)
        .find(|(n, _)| *n == name)
        .map(|&(_, bytes)| bytes)
}

/// Names of the programs meant for users (test_* programs are hidden).
pub fn names() -> impl Iterator<Item = &'static str> {
    USER_PROGRAMS
        .iter()
        .chain(FLAT_PROGRAMS)
        .map(|&(n, _)| n)
        .filter(|n| !n.starts_with("test_"))
}

/// A small prefilled ext2 image (made by build.rs) for the ext2 tests.
pub static EXT2_TEST_IMAGE: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/ext2-test.img"));
